/**
 * Image registry. Every photo currently on the site is ILLUSTRATIVE stock from Wikimedia Commons.
 * None of them show RRJA shipments, staff or premises. Replace them with official RRJA photography when it is supplied.
 *
 * Files live in /public/assets/rrja/<folder>/<id>-<width>.webp (generated by scripts/optimize-images.mjs).
 * Licences that need attribution (CC BY / CC BY-SA) are credited on the /credits page.
 */
export type ImageAsset = {
  id: string
  folder: 'backgrounds' | 'cargo' | 'shipments' | 'office' | 'team'
  alt: string
  width: number
  height: number
  credit: string
  license: string
  source: string
  /** true = not an RRJA photo. Shown with an "Illustrative image" label where context needs it. */
  illustrative: boolean
  /** CSS object-position used when the photo is cropped */
  focus?: string
}

export const widths = [800, 1600, 2400] as const

const c = (file: string) => `https://commons.wikimedia.org/wiki/File:${file}`

