export type ImageKey = keyof typeof images

export const imageSrc = (img: ImageAsset, w: number) => `/assets/rrja/${img.folder}/${img.id}-${w}.webp`
export const imageSrcSet = (img: ImageAsset) =>
  widths.map((w) => `${imageSrc(img, w)} ${w}w`).join(', ')
